initJs:
function(container, apiUrl, tables) {
  let calculationResults = [];

  // エラー・成功メッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    const successText = container.querySelector('#success-text');
    successText.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');
      }
    } catch (error) {
      console.error('店舗データ読み込みエラー:', error);
    }
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="12" class="muted" style="text-align: center; padding: 40px;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id || Math.random()}">
        <td><input type="checkbox" class="result-checkbox" data-id="${result.id || Math.random()}"></td>
        <td>${result.店舗名 || ''}</td>
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td style="text-align: right;">${result.現在在庫数 || 0}</td>
        <td style="text-align: right;">${result.予測需要量 || 0}</td>
        <td style="text-align: right;">${result.安全在庫数 || 0}</td>
        <td style="text-align: right;">${result.発注点 || 0}</td>
        <td style="text-align: right; font-weight: bold;">${result.推奨発注量 || 0}</td>
        <td style="text-align: right;">${(result.発注金額 || 0).toLocaleString()}円</td>
        <td>${result.納期予定日 || ''}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${result.id || Math.random()}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${result.id || Math.random()}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // バリデーション関数
  function validateInputs() {
    const storeSelect = container.querySelector('#store-select');
    const categorySelect = container.querySelector('#category-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const safetyStock = container.querySelector('#safety-stock');
    const leadTime = container.querySelector('#lead-time');
    const orderPoint = container.querySelector('#order-point');

    if (!storeSelect.value && storeSelect.selectedOptions.length === 0) {
      showError('店舗を選択してください');
      return false;
    }

    if (!categorySelect.value) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError('計算対象期間を設定してください');
      return false;
    }

    if (safetyStock.value && parseInt(safetyStock.value) < 0) {
      showError('安全在庫数は0以上の値を入力してください');
      return false;
    }

    if (leadTime.value && parseInt(leadTime.value) <= 0) {
      showError('リードタイムは1以上の値を入力してください');
      return false;
    }

    if (orderPoint.value && isNaN(parseInt(orderPoint.value))) {
      showError('発注点は数値を入力してください');
      return false;
    }

    return true;
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    if (!validateInputs()) return;

    const storeSelect = container.querySelector('#store-select');
    const categorySelect = container.querySelector('#category-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;
    const orderPoint = parseInt(container.querySelector('#order-point').value) || 0;
    const orderCycle = parseInt(container.querySelector('#order-cycle').value) || 7;

    try {
      // 需要予測データ取得
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      const products = await window.aivicApi.list(2); // 商品マスタ
      const stores = await window.aivicApi.list(1); // 店舗マスタ

      if (!forecasts || !products || !stores) {
        showError('データの取得に失敗しました');
        return;
      }

      const selectedStores = Array.from(storeSelect.selectedOptions).map(opt => opt.value);
      const results = [];

      for (const storeId of selectedStores) {
        const store = stores.find(s => s.店舗ID === storeId);
        if (!store) continue;

        const storeForecasts = forecasts.filter(f => 
          f.店舗ID === storeId && 
          f.予測対象日 >= periodStart.value && 
          f.予測対象日 <= periodEnd.value
        );

        for (const forecast of storeForecasts) {
          const product = products.find(p => p.商品ID === forecast.商品ID);
          if (!product) continue;

          // カテゴリフィルタ
          if (categorySelect.value && product.商品カテゴリID !== categorySelect.value) continue;

          const predictedDemand = forecast.予測数量 || 0;
          const currentStock = Math.floor(Math.random() * 100); // 実際は在庫データから取得

          // 発注量計算ロジック
          let recommendedOrder = 0;
          const totalDemand = predictedDemand * orderCycle;
          const requiredStock = totalDemand + safetyStock;

          if (currentStock < orderPoint || currentStock < requiredStock) {
            recommendedOrder = Math.max(0, requiredStock - currentStock);
            // 発注単位で調整
            const orderUnit = product.発注単位 || 1;
            recommendedOrder = Math.ceil(recommendedOrder / orderUnit) * orderUnit;
          }

          const orderAmount = recommendedOrder * (product.単価 || 0);
          const deliveryDate = new Date();
          deliveryDate.setDate(deliveryDate.getDate() + leadTime);

          results.push({
            id: `${storeId}-${forecast.商品ID}-${Date.now()}`,
            店舗名: store.店舗名,
            商品名: product.商品名,
            商品コード: product.商品コード,
            現在在庫数: currentStock,
            予測需要量: predictedDemand,
            安全在庫数: safetyStock,
            発注点: orderPoint,
            推奨発注量: recommendedOrder,
            発注金額: orderAmount,
            納期予定日: deliveryDate.toISOString().split('T')[0],
            店舗ID: storeId,
            商品ID: forecast.商品ID,
            需要予測結果ID: forecast.予測結果ID
          });
        }
      }

      calculationResults = results;
      renderResults(results);

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector('#forecast-display');
      const totalDemand = results.reduce((sum, r) => sum + r.予測需要量, 0);
      forecastDisplay.innerHTML = `
        <h4>需要予測サマリー</h4>
        <p>対象商品数: ${results.length}件</p>
        <p>総予測需要量: ${totalDemand.toLocaleString()}個</p>
        <p>計算期間: ${periodStart.value} ～ ${periodEnd.value}</p>
      `;

      // 在庫状況表示更新
      const inventoryDisplay = container.querySelector('#inventory-display');
      const totalStock = results.reduce((sum, r) => sum + r.現在在庫数, 0);
      const totalOrderAmount = results.reduce((sum, r) => sum + r.発注金額, 0);
      inventoryDisplay.innerHTML = `
        <h4>在庫状況サマリー</h4>
        <p>総在庫数: ${totalStock.toLocaleString()}個</p>
        <p>推奨発注総額: ${totalOrderAmount.toLocaleString()}円</p>
        <p>発注対象商品数: ${results.filter(r => r.推奨発注量 > 0).length}件</p>
      `;

      showSuccess(`発注量計算が完了しました。${results.length}件の結果を表示しています。`);

    } catch (error) {
      console.error('計算エラー:', error);
      showError('発注量計算中にエラーが発生しました');
    }
  }

  // 発注データ生成
  async function generateOrderData() {
    const checkedResults = calculationResults.filter((_, index) => {
      const checkbox = container.querySelector(`input[data-id="${calculationResults[index].id}"]`);
      return checkbox && checkbox.checked;
    });

    if (checkedResults.length === 0) {
      showError('発注データを生成する商品を選択してください');
      return;
    }

    if (!confirm(`${checkedResults.length}件の発注データを生成しますか？`)) {
      return;
    }

    try {
      const orderData = checkedResults.map(result => ({
        店舗ID: result.店舗ID,
        商品ID: result.商品ID,
        需要予測結果ID: result.需要予測結果ID,
        発注日: new Date().toISOString(),
        納期予定日: new Date(result.納期予定日).toISOString(),
        発注数量: result.推奨発注量,
        予測数量: result.予測需要量,
        発注単価: Math.floor(result.発注金額 / result.推奨発注量) || 0,
        発注金額: result.発注金額,
        発注方法: 'AI自動発注',
        発注ステータス: '発注済',
        仕入先ID: 'dummy-supplier-id',
        発注理由: 'AI需要予測に基づく自動発注',
        自動発注フラグ: true,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      }));

      // 発注データを一括保存
      let successCount = 0;
      for (const order of orderData) {
        const saved = await window.aivicApi.save(9, order); // 発注データテーブル
        if (saved) successCount++;
      }

      showSuccess(`${successCount}件の発注データを生成しました`);

      // 発注管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591852463');
      }, 2000);

    } catch (error) {
      console.error('発注データ生成エラー:', error);
      showError('発注データの生成に失敗しました');
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (calculationResults.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['店舗名', '商品名', '商品コード', '現在在庫数', '予測需要量', '安全在庫数', '発注点', '推奨発注量', '発注金額', '納期予定日'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...calculationResults.map(row => [
        `"${row.店舗名}"`,
        `"${row.商品名}"`,
        `"${row.商品コード}"`,
        row.現在在庫数,
        row.予測需要量,
        row.安全在庫数,
        row.発注点,
        row.推奨発注量,
        row.発注金額,
        `"${row.納期予定日}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  renderResults([]);

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#period-start').value = today;
  container.querySelector('#period-end').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  container.querySelector('#btn-bulk-calculate').addEventListener('click', calculateOrderQuantity);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelectorAll('.input').forEach(input => {
      if (input.type === 'checkbox') {
        input.checked = false;
      } else {
        input.value = '';
      }
    });
    calculationResults = [];
    renderResults([]);
    container.querySelector('#forecast-display').innerHTML = '<p class="muted">計算実行後に需要予測結果が表示されます</p>';
    container.querySelector('#inventory-display').innerHTML = '<p class="muted">店舗・商品選択後に在庫状況が表示されます</p>';
  });

  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const filtered = calculationResults.filter(result => 
      result.商品名.toLowerCase().includes(keyword) ||
      result.商品コード.toLowerCase().includes(keyword) ||
      result.店舗名.toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  });

  container.querySelector('#btn-generate-order').addEventListener('click', generateOrderData);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.result-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この計算結果を削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      calculationResults = calculationResults.filter(r => r.id !== id);
      renderResults(calculationResults);
      showSuccess('計算結果を削除しました');
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const id = editBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result) {
        const newQuantity = prompt('推奨発注量を修正してください:', result.推奨発注量);
        if (newQuantity !== null && !isNaN(newQuantity)) {
          result.推奨発注量 = parseInt(newQuantity);
          result.発注金額 = result.推奨発注量 * (result.発注金額 / (result.推奨発注量 || 1));
          renderResults(calculationResults);
          showSuccess('発注量を修正しました');
        }
      }
    }
  });
}
